<script>
export default {
  props: {
    chat: {
      type: Object,
      required: true
    },
    index: {
      type: Number,
      required: true
    },
    isSelected: {
      type: Boolean,
      default: false
    },
    isDragged: {
      type: Boolean,
      default: false
    },
    isDragOver: {
      type: Boolean,
      default: false
    },
    depth: {
      type: Number,
      default: 0
    },
    allChats: {
      type: Array,
      default: () => []
    },
    projectIcon: {
      type: String,
      required: true
    },
    isUpdating: {
      type: Boolean,
      default: false
    },
    selectedChatId: {
      type: String,
      default: null
    },
    draggedItemId: {
      type: String,
      default: null
    }
  },
  computed: {
    nestedChildren() {
      return this.allChats
        .filter(c => c.parent_id === this.chat.id)
