    <!-- Nested Children -->
    <div v-if="isExpanded && hasChildren" class="ml-4 flex flex-col gap-1 border-l border-base-content/10 pl-2 py-1">
      <ChatNavigatorNode
        v-for="child in children"
        :key="child.id"
        :chat="child"
        :allChats="allChats"
        :selectedChatId="selectedChatId"
        :depth="depth + 1"
        @select="$emit('select', $event)"
      />
    </div>
  </div>
</template>

<script>
export default {
  props: {
    chat: {
      type: Object,
      required: true
    },
    allChats: {
      type: Array,
      required: true
    },
    selectedChatId: {
      type: String,
      default: null
    },
    depth: {
      type: Number,
      default: 0
    }
  },
  data() {
    return {
      isExpanded: this.depth < 2 // Auto expand first 2 levels
    }
  },
  computed: {
    children() {
      return this.allChats
        .filter(c => c.parent_id === this.chat.id)
        .sort((a, b) => a.name > b.name ? 1 : -1)
    },
    hasChildren() {
      return this.children.length > 0
    },
    isSelected() {
      return this.selectedChatId === this.chat.id
    }
  },
  methods: {
    toggleExpand() {
      this.isExpanded = !this.isExpanded
    }
  }
}
</script>
